package com.cyancoder.report.service;
import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpHeaders;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class ReportMediaClient{private final RestClient client;private final String auth;public ReportMediaClient(RestClient.Builder b,@Value("${media-service.base-url:http://localhost:9116}")String url,@Value("${media-service.internal.username:media_internal}")String user,@Value("${media-service.internal.password:media_secret}")String pass){client=b.baseUrl(url).build();auth="Basic "+Base64.getEncoder().encodeToString((user+":"+pass).getBytes(StandardCharsets.UTF_8));}
 public Map<?,?> upload(String tenant,String site,String fileName,String mime,byte[] bytes,String exportId){Map<?,?> result=client.post().uri("/internal/media/assets/generated").header(HttpHeaders.AUTHORIZATION,auth).header("X-Tenant-Key",tenant).headers(h->{if(site!=null&&!site.isBlank())h.set("X-Site-Key",site);}).body(Map.of("fileName",fileName,"mimeType",mime,"base64",Base64.getEncoder().encodeToString(bytes),"generatedBy","report-export:"+exportId,"retentionDays",30)).retrieve().body(Map.class);String asset=Objects.toString(result==null?null:result.get("assetKey"),null);if(asset!=null)client.put().uri("/internal/media/assets/{asset}/references",asset).header(HttpHeaders.AUTHORIZATION,auth).header("X-Tenant-Key",tenant).headers(h->{if(site!=null&&!site.isBlank())h.set("X-Site-Key",site);}).body(Map.of("ownerService","report-service","ownerType","REPORT_EXPORT","ownerKey",exportId,"fieldPath","assetKey")).retrieve().toBodilessEntity();return result;}
}
